+    let err = project::load(&new_world(), &c).expect_err("a hole without its mark is corrupt");
+    assert!(err.to_string().contains("names a mesh hole but is not a model marked fidelity unknown"), "{err}");
+    for f in [a, b, c] {
+        let _ = std::fs::remove_file(f);
+    }
+}

